//! UNDO + MOVE_ONTO + HOUSEKEEPING + FLAVOR_17X scenario buckets — generated by generate_matrix.py tooling.
//!
//! One #[test] per (family x observation x repeat) bucket. Each bucket runs
//! its scenarios through gt_sim::run_scenario and reports every violation in
//! a single panic, prefixed with stable scenario IDs for triage. See PLAN.md.

use super::gt_sim;
use super::scenario;

fn run_bucket(family: &str, observation: &str, repeat: &str) {
    let scenarios: Vec<_> = scenario::family(family)
        .into_iter()
        .filter(|s| s.observation == observation && s.repeat == repeat)
        .collect();
    assert!(!scenarios.is_empty(), "empty bucket {family}/{observation}/{repeat}");
    let mut violations = Vec::new();
    for s in &scenarios {
        violations.extend(gt_sim::run_scenario(s));
    }
    assert!(
        violations.is_empty(),
        "{} attribution violations in {} {}/{} ({} scenarios):\n{}",
        violations.len(),
        family,
        observation,
        repeat,
        scenarios.len(),
        violations.join("\n")
    );
}

#[test]
fn undo_blind_once() {
    run_bucket("UNDO", "blind", "once");
}

#[test]
fn undo_blind_twice() {
    run_bucket("UNDO", "blind", "twice");
}

#[test]
fn undo_traced_once() {
    run_bucket("UNDO", "traced", "once");
}

#[test]
fn undo_traced_twice() {
    run_bucket("UNDO", "traced", "twice");
}

#[test]
fn move_onto_blind_once() {
    run_bucket("MOVE_ONTO", "blind", "once");
}

#[test]
fn move_onto_traced_once() {
    run_bucket("MOVE_ONTO", "traced", "once");
}

#[test]
fn housekeeping_traced_twice() {
    run_bucket("HOUSEKEEPING", "traced", "twice");
}

#[test]
fn flavor_17x_traced_once() {
    run_bucket("FLAVOR_17X", "traced", "once");
}

